#!/usr/bin/env bash
# Uploads the role tokens from 1Password to the deployed Worker as Wrangler secrets.
# Each value goes from `op read` straight into `wrangler secret put`; no value is printed.
#
#   scripts/put-secrets.sh [--generate] [role ...]
#
#   role        orchestrator, creative-director, developer or human (default: all four)
#   --generate  first give each role's 1Password item a new value generated by 1Password itself
#               (the item is created if missing). This rotates the token: update that role's
#               connector URL, Claude Code header and Mod setting afterwards. If an upload fails
#               after --generate, re-run without --generate to upload the new values.
#
# 1Password references: OP_REF_ORCHESTRATOR, OP_REF_CREATIVE_DIRECTOR, OP_REF_DEVELOPER and
# OP_REF_HUMAN, each defaulting to "op://Agent Relay/<Role> token/password".
set -euo pipefail

RECIPE="letters,digits,48"
MIN_LENGTH=32

usage() { awk 'NR > 1 && /^#/ { sub(/^# ?/, ""); print; next } NR > 1 { exit }' "$0"; }

upper() { printf '%s' "$1" | tr 'a-z-' 'A-Z_'; }

item_title() {
  case "$1" in
    orchestrator) echo "Orchestrator token" ;;
    creative-director) echo "Creative Director token" ;;
    developer) echo "Developer token" ;;
    human) echo "Human token" ;;
  esac
}

op_ref() {
  local var
  var="OP_REF_$(upper "$1")"
  printf '%s' "${!var:-op://Agent Relay/$(item_title "$1")/password}"
}

# Gives the item behind an op://<vault>/<item>/password reference a new generated password,
# creating a Password item if there is none. The value never passes through this script.
generate() {
  local ref="$1" rest vault item field
  rest="${ref#op://}"
  vault="${rest%%/*}"
  rest="${rest#*/}"
  item="${rest%%/*}"
  field="${rest#*/}"
  if [[ "$ref" != op://*/*/* || "$field" != "password" ]]; then
    echo "--generate needs a reference like op://<vault>/<item>/password, not $ref" >&2
    exit 1
  fi
  if op item get "$item" --vault "$vault" >/dev/null 2>&1; then
    op item edit "$item" --vault "$vault" --generate-password="$RECIPE" >/dev/null
  else
    op item create --category Password --vault "$vault" --title "$item" --generate-password="$RECIPE" >/dev/null
  fi
}

upload() {
  local role="$1" ref name token
  ref="$(op_ref "$role")"
  name="$(upper "$role")_TOKEN"
  token="$(op read --no-newline "$ref")"
  # The relay disables roles with short tokens, and claude.ai connectors carry the token in the URL path.
  if [[ ${#token} -lt $MIN_LENGTH || ! "$token" =~ ^[A-Za-z0-9._~-]+$ ]]; then
    echo "$ref must hold at least $MIN_LENGTH URL-safe characters (letters, digits, - _ . ~); $name not uploaded." >&2
    exit 1
  fi
  printf '%s' "$token" | npx wrangler secret put "$name"
}

rotate=false
roles=()
for arg in "$@"; do
  case "$arg" in
    --generate) rotate=true ;;
    -h | --help) usage; exit 0 ;;
    orchestrator | creative-director | developer | human) roles+=("$arg") ;;
    *) printf 'Unknown argument: %s\n\n' "$arg" >&2; usage >&2; exit 2 ;;
  esac
done
[[ ${#roles[@]} -gt 0 ]] || roles=(orchestrator creative-director developer human)

command -v op >/dev/null || { echo "1Password CLI (op) not found; install it first." >&2; exit 1; }
if ! op whoami >/dev/null 2>&1; then
  echo "Not signed in to 1Password: run  eval \"\$(op signin)\"  (or unlock the 1Password app) and retry." >&2
  exit 1
fi

cd "$(dirname "$0")/.."
for role in "${roles[@]}"; do
  if $rotate; then generate "$(op_ref "$role")"; fi
  upload "$role"
done

if $rotate; then
  echo "Rotated: ${roles[*]}. Update each one's connector URL, Claude Code header and Mod role_token."
fi
